using System.Collections.Generic; using UnityEngine; public class CategoryZone : MonoBehaviour { public int columns = 2; public float spacingX = 1.05f; public float spacingY = 0.72f; public float startY = 0.65f; public float surfaceOffset = -0.16f; private readonly List<StickyNote> placedNotes = new List<StickyNote>(); public void PlaceNote(StickyNote note) { if (note == null) { return; } if (note.CurrentZone != null && note.CurrentZone != this) { note.CurrentZone.RemoveNote(note); } if (!placedNotes.Contains(note)) { placedNotes.Add(note); } note.CurrentZone = this; note.transform.SetParent(transform); RepositionNotes(); } public void RemoveNote(StickyNote note) { if (note == null) { return; } placedNotes.Remove(note); if (note.CurrentZone == this) { note.CurrentZone = null; } RepositionNotes(); } void RepositionNotes() { for (int i = 0; i < placedNotes.Count; i++) { int row = i / columns; int column = i % columns; float x = (column - (columns - 1) * 0.5f) * spacingX; float y = startY - row * spacingY; StickyNote note = placedNotes[i]; note.transform.localPosition = new Vector3(x, y, surfaceOffset); note.transform.localRotation = Quaternion.identity; } } }